function authPage(register = false) {
  const socialLogin = register ? '' : `<div class="auth-divider"><span>OR</span></div><div class="auth-social-buttons" role="group" aria-label="Alternative sign-in options"><button class="auth-social-button" type="button" data-action="social-signin" data-provider="Google" aria-label="Continue with Google">${brandIcon('google', 19)}<span>Continue with Google</span></button><button class="auth-social-button" type="button" data-action="social-signin" data-provider="Apple" aria-label="Continue with Apple">${brandIcon('apple', 19)}<span>Continue with Apple</span></button></div><p class="auth-social-note"></p>`;
  return `<main id="main-content" class="auth-main auth-page"><div class="auth-decoration"><div class="auth-decoration-grid"></div><div class="auth-photo"><img src="/assets/facility-hero.jpg" alt="Facilities engineer reviewing a modern building control panel"/></div><div class="auth-quote"><span>“</span><p>A well-run building gives its people more room to do their best work.</p><small>NORTHLINE OPERATIONS PRINCIPLE</small></div></div><div class="auth-side"><div class="auth-card">${logo()}<span class="eyebrow">${register ? 'ACCOUNT REGISTRATION PREVIEW' : 'CLIENT WORKSPACE ACCESS'}</span><h1>${register ? 'Preview account registration.' : 'Welcome back.'}</h1><p>${register ? 'Try the registration flow. No account is created, and your details are not saved.' : ''}</p><form data-form="auth" data-register="${register}" class="auth-form" novalidate>${register ? `<label>Full name<input name="name" required minlength="2" autocomplete="name" placeholder="e.g. Ananya Iyer"/></label><label>Company<input name="company" required autocomplete="organization" placeholder="Your organisation"/></label>` : ''}<label>Work email<input name="email" type="email" required autocomplete="email" placeholder="you@company.in"/></label>${register ? '<label>Phone number<input name="phone" type="tel" inputmode="tel" autocomplete="tel" required pattern="(\\+91[ -]?)?[6-9][0-9]{9}" title="Enter a 10-digit Indian mobile number, with an optional +91 country code." placeholder="+91 98765 43210"/></label>' : ''}<label>Password<div class="password-field"><input name="password" type="password" required minlength="8" autocomplete="${register ? 'new-password' : 'current-password'}" placeholder="${register ? 'At least 8 characters' : 'Enter any 8 or more characters in this preview'}"/><button type="button" data-action="toggle-password" aria-label="Show password">${icon('eye', 17)}</button></div></label>${register ? `<label>Confirm password<input name="confirmPassword" type="password" required minlength="8" autocomplete="new-password" placeholder="Enter your password again"/></label><label class="form-check auth-check"><input type="checkbox" name="terms" required/><span>I agree to the <a href="#/terms">Terms of Service</a> and <a href="#/privacy">Privacy Policy</a>.</span></label>` : `<div class="auth-form-row"><label class="form-check"><input type="checkbox" name="remember"/><span>Remember me</span></label><a href="#/forgot-password">Forgot password?</a></div>`}<div class="form-feedback" aria-live="polite"></div><button type="submit" class="btn btn-primary auth-submit">${register ? 'Preview registration' : 'Continue to workspace preview'} ${icon('arrow', 15)}</button></form>${socialLogin}<p class="auth-switch">${register ? 'Already have access?' : 'New to Northline?'} <a href="#/${register ? 'login' : 'register'}">${register ? 'Return to Login' : 'Try registration'}</a></p><div class="auth-security"></div></div></div></main>`;
}

